local EXPORT_FILENAME = "psw_talent_state.json"

local function json_string(value)
    local text = tostring(value or "")
    text = string.gsub(text, "\\", "\\\\")
    text = string.gsub(text, '"', '\\"')
    text = string.gsub(text, "\r", "\\r")
    text = string.gsub(text, "\n", "\\n")
    return '"' .. text .. '"'
end

local function faction_talent_bundle(faction, talent_key)
    local candidates = {
        "set_" .. talent_key,
        "set_main_" .. talent_key
    }
    for i = 1, #candidates do
        local bundle = candidates[i]
        local ok, active = pcall(function()
            return faction:has_effect_bundle(bundle)
        end)
        if ok and active == true then
            return bundle
        end
    end
    return nil
end

local function export_faction(faction)
    local active = {}
    local bundles = {}
    for i = 1, #TALENT_KEYS do
        local talent_key = TALENT_KEYS[i]
        local bundle = faction_talent_bundle(faction, talent_key)
        local global_key = "set_main_" .. talent_key
        local global_active = psw_main_data
            and psw_main_data.global_data
            and psw_main_data.global_data[global_key] == true
        if bundle or global_active then
            table.insert(active, talent_key)
            table.insert(bundles, bundle or global_key .. " [global]")
        end
    end
    return {
        key = faction:name(),
        active = active,
        bundles = bundles
    }
end

local function export_state()
    local rows = {}
    local factions = cm:model():world():faction_list()
    for i = 0, factions:num_items() - 1 do
        local faction = factions:item_at(i)
        if faction and not faction:is_null_interface() and faction:is_human() then
            local row = export_faction(faction)
            local active = {}
            for j = 1, #row.active do
                table.insert(active, json_string(row.active[j]))
            end
            local bundles = {}
            for j = 1, #row.bundles do
                table.insert(bundles, json_string(row.bundles[j]))
            end
            table.insert(rows,
                "{" ..
                '"key":' .. json_string(row.key) ..
                ',"active":[' .. table.concat(active, ",") ..
                '],"bundles":[' .. table.concat(bundles, ",") .. "]}"
            )
        end
    end

    local file, error_message = io.open(EXPORT_FILENAME, "w")
    if not file then
        out("[psw_talent_state_export] unable to write " .. EXPORT_FILENAME ..
            ": " .. tostring(error_message))
        return
    end
    local document =
        '{"schema":1,"source":"psw_talent_state_export","turn":' ..
        tostring(cm:model():turn_number()) ..
        ',"factions":[' .. table.concat(rows, ",") .. "]}"
    file:write(document)
    file:close()
    out("[psw_talent_state_export] wrote " .. EXPORT_FILENAME)
end

cm:add_first_tick_callback(function()
    export_state()
end)

core:add_listener(
    "czx_psw_talent_state_export_faction_turn",
    "FactionTurnStart",
    function(context)
        return context:faction() and context:faction():is_human()
    end,
    function()
        export_state()
    end,
    true
)
